solution:
fn are_equal[T: Eq](a: T, b: T) -> Bool {
  return a == b;
}

fn is_greater[T: Ord](a: T, b: T) -> Bool {
  return a > b;
}

fn main() -> Int {
  if are_equal[Int](42, 42) && is_greater[Int](10, 5) {
    return 1;
  }
  return 0;
}
